    ),
    "parameters": {
        "type": "object",
        "properties": {
            "booking_id": {"type": "string", "description": "The booking ID to cancel"},
            "confirm": {
                "type": "boolean",
                "description": "Confirm the cancellation after reviewing the terms.",
            },
        },
        "required": ["booking_id"],
